"""``OfferAi`` on pydantic-ai agents."""

import logging
from functools import cache
from importlib import resources

import httpx
from pydantic_ai import Agent
from pydantic_ai.exceptions import ModelHTTPError, UnexpectedModelBehavior
from pydantic_ai.models import Model
from pydantic_ai.models.openai import OpenAIChatModel
from pydantic_ai.providers.azure import AzureProvider
from pydantic_ai.settings import ModelSettings
from pydantic_ai.usage import UsageLimits

from alloq_offer.workshop.ai.demo import DemoOfferAi
from alloq_offer.workshop.ai.port import (
    AiTransientError,
    AiUnavailableError,
    ChapterRequest,
    MapRequest,
    ReviewRequest,
    SourceText,
)
from alloq_offer.workshop.ai.render import (
    render_chapter,
    render_map_request,
    render_review,
    render_sources,
)
from alloq_offer.workshop.ai.schemas import (
    ProposedBriefing,
    ProposedChapter,
    ProposedMap,
    ProposedReview,
)
from alloq_offer.workshop.configuration import WorkshopConfig

logger = logging.getLogger(__name__)

MAP_PROMPT = "map_v1"
BRIEFING_PROMPT = "briefing_v1"
MAP_ADDITIONS_PROMPT = "map_additions_v1"
CHAPTER_PROMPT = "chapter_v1"
REVIEW_PROMPT = "review_v1"
NOT_CONFIGURED = (
    "Die KI ist nicht eingerichtet. Bitte hinterlegen Sie den Azure-OpenAI-Zugang "
    "in der Konfiguration."
)
RATE_LIMITED = 429
SERVER_ERROR = 500


@cache
def load_prompt(name: str) -> str:
    return (
        resources.files("alloq_offer.workshop.ai.prompts")
        .joinpath(f"{name}.md")
        .read_text(encoding="utf-8")
    )


def build_azure_model(config: WorkshopConfig) -> Model:
    azure = config.azure_openai
    if not (azure.endpoint and azure.chat_deployment):
        raise AiUnavailableError(NOT_CONFIGURED)
    provider = AzureProvider(
        azure_endpoint=azure.endpoint,
        api_version=azure.api_version,
        api_key=REDACTED,
    )
    return OpenAIChatModel(azure.chat_deployment, provider=provider)


class PydanticOfferAi:
    """Proposals from a pydantic-ai model; outputs are validated or retried."""

    map_prompt_version = MAP_PROMPT
    briefing_prompt_version = BRIEFING_PROMPT
    chapter_prompt_version = CHAPTER_PROMPT
    review_prompt_version = REVIEW_PROMPT
    map_additions_prompt_version = MAP_ADDITIONS_PROMPT

    def __init__(self, model: Model, config: WorkshopConfig, name: str) -> None:
        self._model = model
        self._config = config
        self.model_name = name

    async def _run[T](
        self, output: type[T], prompt: str, user_prompt: str, label: str
    ) -> T:
        agent = Agent(
            self._model,
            name=label,
            output_type=output,
            instructions=load_prompt(prompt),
            retries=2,
            model_settings=ModelSettings(timeout=self._config.ai_timeout_seconds),
        )
        try:
            result = await agent.run(
                user_prompt,
                usage_limits=UsageLimits(request_limit=self._config.ai_request_limit),
            )
        except ModelHTTPError as exc:
            if exc.status_code == RATE_LIMITED or exc.status_code >= SERVER_ERROR:
                raise AiTransientError(label) from exc
            raise AiUnavailableError(label) from exc
        except (httpx.TransportError, TimeoutError) as exc:
            raise AiTransientError(label) from exc
        except UnexpectedModelBehavior as exc:
            raise AiUnavailableError(label) from exc
        usage = result.usage
        logger.info(
            "Model run %s: %d requests, %d input and %d output tokens",
            label,
            usage.requests,
            usage.input_tokens,
            usage.output_tokens,
        )
        return result.output

    async def propose_map(self, sources: list[SourceText]) -> ProposedMap:
        data = render_sources(sources, self._config.ai_max_input_chars)
        return await self._run(ProposedMap, MAP_PROMPT, data, "propose_map")

    async def propose_briefing(self, sources: list[SourceText]) -> ProposedBriefing:
        data = render_sources(sources, self._config.ai_max_input_chars)
        return await self._run(
            ProposedBriefing, BRIEFING_PROMPT, data, "propose_briefing"
        )

    async def propose_chapter(self, request: ChapterRequest) -> ProposedChapter:
        data = render_chapter(request, self._config.ai_max_input_chars)
        return await self._run(ProposedChapter, CHAPTER_PROMPT, data, "propose_chapter")

    async def propose_map_additions(self, request: MapRequest) -> ProposedMap:
        data = render_map_request(request, self._config.ai_max_input_chars)
        return await self._run(
            ProposedMap, MAP_ADDITIONS_PROMPT, data, "propose_map_additions"
        )

    async def propose_review(self, request: ReviewRequest) -> ProposedReview:
        data = render_review(request, self._config.ai_max_input_chars)
        return await self._run(ProposedReview, REVIEW_PROMPT, data, "propose_review")


def create_offer_ai(config: WorkshopConfig) -> PydanticOfferAi | DemoOfferAi:
    """The configured model; ``demo`` quotes the sources instead of a model."""
    if config.ai_provider == "demo":
        return DemoOfferAi()
    return PydanticOfferAi(
        build_azure_model(config), config, config.azure_openai.chat_deployment
    )
"""The port to the language model; the rest of the workshop only knows this."""

from dataclasses import dataclass, field
from typing import Protocol

from alloq_offer.workshop.ai.schemas import (
    ProposedBriefing,
    ProposedChapter,
    ProposedMap,
    ProposedReview,
)


@dataclass(frozen=True)
class BlockText:
    id: int
    text: str
    label: str = ""
    speaker: str | None = None


@dataclass(frozen=True)
class SourceText:
    """One source as data for a prompt."""

    id: int
    title: str
    kind: str
    blocks: list[BlockText] = field(default_factory=list)
    gaps: list[str] = field(default_factory=list)


@dataclass(frozen=True)
class ChapterRequest:
    """What the model gets to know when it drafts or reworks one chapter."""

    title: str
    guiding_question: str
    rules: list[str]
    current_lines: list[str]
    instruction: str
    map_outline: str
    statements: list[str]


@dataclass(frozen=True)
class ReviewChapter:
    key: str
    title: str
    lines: list[str]


@dataclass(frozen=True)
class ReviewRequest:
    """The offer as the review reads it: map, briefing and written chapters."""

    map_outline: str
    statements: list[str]
    chapters: list[ReviewChapter]


@dataclass(frozen=True)
class MapRequest:
    """A wish for more of the map: the current map, the briefing and the sources."""

    instruction: str
    map_outline: str
    statements: list[str]
    sources: list[SourceText]


class AiUnavailableError(RuntimeError):
    """No model is configured or it cannot be reached for good."""


class AiTransientError(RuntimeError):
    """The model call may work on a later attempt (timeout, rate limit)."""


class OfferAi(Protocol):
    model_name: str
    map_prompt_version: str
    briefing_prompt_version: str

    async def propose_map(self, sources: list[SourceText]) -> ProposedMap: ...

    async def propose_briefing(self, sources: list[SourceText]) -> ProposedBriefing: ...


class ChapterAi(Protocol):
    model_name: str
    chapter_prompt_version: str

    async def propose_chapter(self, request: ChapterRequest) -> ProposedChapter: ...


class ReviewAi(Protocol):
    model_name: str
    review_prompt_version: str

    async def propose_review(self, request: ReviewRequest) -> ProposedReview: ...


class MapAdditionAi(Protocol):
    model_name: str
    map_additions_prompt_version: str

    async def propose_map_additions(self, request: MapRequest) -> ProposedMap: ...
"""Sources as clearly delimited data for a prompt."""

from alloq_offer.workshop.ai.port import (
    ChapterRequest,
    MapRequest,
    ReviewRequest,
    SourceText,
)

TRUNCATED = "[Weitere Quellen wurden wegen der Länge ausgelassen.]"


def _escape(text: str) -> str:
    return text.replace("</quelle>", "<\\/quelle>").replace("<quelle", "<\\quelle")


def render_sources(sources: list[SourceText], max_chars: int) -> str:
    """One ``<quelle>`` block per source; whole sources are dropped past the budget."""
    parts: list[str] = []
    used = 0
    for source in sources:
        lines = [f'<quelle id="{source.id}" art="{_escape(source.kind)}">']
        lines.append(f"Titel: {_escape(source.title)}")
        for block in source.blocks:
            speaker = f"{block.speaker}: " if block.speaker else ""
            label = f" ({block.label})" if block.label else ""
            lines.append(f"[B{block.id}]{label} {speaker}{_escape(block.text)}")
        lines.extend(f"[Lücke] {_escape(gap)}" for gap in source.gaps)
        lines.append("</quelle>")
        text = "\n".join(lines)
        if parts and used + len(text) > max_chars:
            parts.append(TRUNCATED)
            break
        parts.append(text)
        used += len(text)
    return "\n\n".join(parts)


CONFIRMED_MARK = " (fachlich bestätigt)"


def statement_line(type_: str, text: str, confirmed: bool) -> str:
    """A briefing statement as one prompt line."""
    return f"{type_}: {text}" + (CONFIRMED_MARK if confirmed else "")


def map_outline(snapshot: dict) -> str:
    """The live part of a map snapshot as indented text: activities, tasks, stories."""
    lines: list[str] = []
    if snapshot["vision"]:
        lines.append(f"Vision: {snapshot['vision']}")
    for activity in snapshot["activities"]:
        if activity["archived"]:
            continue
        lines.append(f"Aktivität: {activity['title']}")
        for task in activity["tasks"]:
            if task["archived"]:
                continue
            lines.append(f"  Aufgabe: {task['title']}")
            lines.extend(
                f"    {story['key']} {story['title']}: {story['sentence']}"
                for story in task["stories"]
                if not story["archived"]
            )
    return "\n".join(lines)


def _tags(text: str) -> str:
    """Neutralise angle brackets so text cannot close or open a delimiter."""
    return text.replace("<", "&lt;").replace(">", "&gt;")


def render_chapter(request: ChapterRequest, max_chars: int) -> str:
    """The chapter task with map and briefing as delimited data."""
    parts = [
        f'<kapitel titel="{_tags(request.title)}">',
        f"Leitfrage: {_tags(request.guiding_question)}",
        *(f"Regel: {_tags(rule)}" for rule in request.rules),
        "</kapitel>",
    ]
    if request.current_lines:
        lines = [_tags(line) for line in request.current_lines]
        parts += ["<aktueller_text>", *lines, "</aktueller_text>"]
    if request.instruction:
        parts += ["<anweisung>", _tags(request.instruction), "</anweisung>"]
    parts += ["<map>", _tags(request.map_outline)[:max_chars], "</map>"]
    parts += ["<briefing>", *map(_tags, request.statements), "</briefing>"]
    return "\n".join(parts)


def render_review(request: ReviewRequest, max_chars: int) -> str:
    """Map, briefing and chapters as delimited data for the review."""
    parts = ["<map>", _tags(request.map_outline), "</map>"]
    parts += ["<briefing>", *map(_tags, request.statements), "</briefing>"]
    for chapter in request.chapters:
        parts += [
            f'<kapitel key="{_tags(chapter.key)}" titel="{_tags(chapter.title)}">'
        ]
        parts += [*map(_tags, chapter.lines), "</kapitel>"]
    return "\n".join(parts)[:max_chars]


def render_map_request(request: MapRequest, max_chars: int) -> str:
    """Instruction, current map and briefing, then the sources as delimited data."""
    parts = ["<anweisung>", _tags(request.instruction), "</anweisung>"]
    parts += ["<map>", _tags(request.map_outline), "</map>"]
    parts += ["<briefing>", *map(_tags, request.statements), "</briefing>"]
    head = "\n".join(parts)
    sources = render_sources(request.sources, max(max_chars - len(head), 0))
    return f"{head}\n\n{sources}"
    if text.endswith("?"):
        return StatementType.OPEN_POINT
    if ASSUMPTION.match(text):
        return StatementType.ASSUMPTION
    if REQUIREMENT.match(text):
        return StatementType.REQUIREMENT
    return StatementType.FACT


def _runs(text: str) -> list[Run]:
    return [Run(text=text)]


def _wanted_types(title: str) -> tuple[str, ...]:
    lowered = title.lower()
    if "annahme" in lowered or "risik" in lowered:
        return (StatementType.ASSUMPTION, StatementType.OPEN_POINT)
    if "rahmen" in lowered or "abwicklung" in lowered or "laufzeit" in lowered:
        return (StatementType.FACT, StatementType.ASSUMPTION)
    return (StatementType.REQUIREMENT, StatementType.FACT)


class DemoOfferAi:
    """Implements every AI port by quoting the sources; no network, no model."""

    model_name = DEMO_MODEL
    map_prompt_version = DEMO_PROMPT
    briefing_prompt_version = DEMO_PROMPT
    chapter_prompt_version = DEMO_PROMPT
    review_prompt_version = DEMO_PROMPT
    map_additions_prompt_version = DEMO_PROMPT

    async def propose_map(self, sources: list[SourceText]) -> ProposedMap:
        activities: list[ProposedActivity] = []
        for source in sources:
            stories = [
                story
                for sentence in _sentences(source)
                if (story := _story(sentence)) is not None
            ][:MAX_STORIES_PER_SOURCE] or [_fallback_story(source)]
            for position, story in enumerate(stories):
                story.skeleton = position == 0
                story.slice = SLICES[0] if position == 0 else SLICES[1]
            activities.append(
                ProposedActivity(
                    title=_source_name(source)[:120],
                    tasks=[ProposedTask(title=TASK_TITLE, stories=stories)],
                )
            )
        names = ", ".join(_source_name(source) for source in sources)
        return ProposedMap(
            vision=f"Angebot auf Grundlage von: {names}"[:500],
            roles=sorted(
                {
                    story.role
                    for activity in activities
                    for task in activity.tasks
                    for story in task.stories
                }
            ),
            activities=activities,
            slices=list(SLICES),
            open_questions=[
                ProposedPoint(text=f"In „{_source_name(source)}“ fehlt: {gap}")
                for source in sources
                for gap in source.gaps
            ],
        )

    async def propose_briefing(self, sources: list[SourceText]) -> ProposedBriefing:
        statements = [
            ProposedStatement(
                type=_statement_type(sentence.text),
                text=sentence.text,
                source_refs=[sentence.block_id],
            )
            for source in sources
            for sentence in _sentences(source)
        ]
        return ProposedBriefing(statements=statements[:MAX_STATEMENTS])

    async def propose_chapter(self, request: ChapterRequest) -> ProposedChapter:
        wanted = _wanted_types(request.title)
        items = [
            text
            for line in request.statements
            for kind, _, text in [line.partition(": ")]
            if kind in wanted
        ][:MAX_CHAPTER_ITEMS]
        if not items:
            note = EMPTY_CHAPTER.format(title=request.title)
            return ProposedChapter(blocks=[Paragraph(runs=_runs(note))])
        intro = CHAPTER_INTRO.format(title=request.title)
        return ProposedChapter(
            blocks=[
                Paragraph(runs=_runs(intro)),
                BulletList(items=[_runs(item) for item in items]),
            ]
        )

    async def propose_review(self, request: ReviewRequest) -> ProposedReview:
        return ProposedReview(
            findings=[
                ReviewRemark(
                    target=f"chapter:{chapter.key}",
                    message=REVIEW_EMPTY,
                    severity="Warnung",
                )
                for chapter in request.chapters
                if len(chapter.lines) < 2  # noqa: PLR2004  # intro plus one point
            ]
        )

    async def propose_map_additions(self, request: MapRequest) -> ProposedMap:
        proposed = await self.propose_map(request.sources)
        for activity in proposed.activities:
            for task in activity.tasks:
                task.stories = [
                    s for s in task.stories if s.goal not in request.map_outline
                ]
        proposed.activities = [
            a for a in proposed.activities if any(t.stories for t in a.tasks)
        ]
        proposed.open_questions = []
        return proposed

