"""Sources as clearly delimited data for a prompt."""

from alloq_offer.workshop.ai.port import (
    ChapterRequest,
    MapRequest,
    ReviewRequest,
    SourceText,
)

TRUNCATED = "[Weitere Quellen wurden wegen der Länge ausgelassen.]"


def _escape(text: str) -> str:
    return text.replace("</quelle>", "<\\/quelle>").replace("<quelle", "<\\quelle")


def render_sources(sources: list[SourceText], max_chars: int) -> str:
    """One ``<quelle>`` block per source; whole sources are dropped past the budget."""
    parts: list[str] = []
    used = 0
    for source in sources:
        lines = [f'<quelle id="{source.id}" art="{_escape(source.kind)}">']
        lines.append(f"Titel: {_escape(source.title)}")
        for block in source.blocks:
            speaker = f"{block.speaker}: " if block.speaker else ""
            label = f" ({block.label})" if block.label else ""
            lines.append(f"[B{block.id}]{label} {speaker}{_escape(block.text)}")
        lines.extend(f"[Lücke] {_escape(gap)}" for gap in source.gaps)
        lines.append("</quelle>")
        text = "\n".join(lines)
        if parts and used + len(text) > max_chars:
            parts.append(TRUNCATED)
            break
        parts.append(text)
        used += len(text)
    return "\n\n".join(parts)


CONFIRMED_MARK = " (fachlich bestätigt)"


def statement_line(type_: str, text: str, confirmed: bool) -> str:
    """A briefing statement as one prompt line."""
    return f"{type_}: {text}" + (CONFIRMED_MARK if confirmed else "")


def map_outline(snapshot: dict) -> str:
    """The live part of a map snapshot as indented text: activities, tasks, stories."""
    lines: list[str] = []
    if snapshot["vision"]:
        lines.append(f"Vision: {snapshot['vision']}")
    for activity in snapshot["activities"]:
        if activity["archived"]:
            continue
        lines.append(f"Aktivität: {activity['title']}")
        for task in activity["tasks"]:
            if task["archived"]:
                continue
            lines.append(f"  Aufgabe: {task['title']}")
            lines.extend(
                f"    {story['key']} {story['title']}: {story['sentence']}"
                for story in task["stories"]
                if not story["archived"]
            )
    return "\n".join(lines)


def _tags(text: str) -> str:
    """Neutralise angle brackets so text cannot close or open a delimiter."""
    return text.replace("<", "&lt;").replace(">", "&gt;")


def render_chapter(request: ChapterRequest, max_chars: int) -> str:
    """The chapter task with map and briefing as delimited data."""
    parts = [
        f'<kapitel titel="{_tags(request.title)}">',
        f"Leitfrage: {_tags(request.guiding_question)}",
        *(f"Regel: {_tags(rule)}" for rule in request.rules),
        "</kapitel>",
    ]
    if request.current_lines:
        lines = [_tags(line) for line in request.current_lines]
        parts += ["<aktueller_text>", *lines, "</aktueller_text>"]
    if request.instruction:
        parts += ["<anweisung>", _tags(request.instruction), "</anweisung>"]
    parts += ["<map>", _tags(request.map_outline)[:max_chars], "</map>"]
    parts += ["<briefing>", *map(_tags, request.statements), "</briefing>"]
    return "\n".join(parts)


def render_review(request: ReviewRequest, max_chars: int) -> str:
    """Map, briefing and chapters as delimited data for the review."""
    parts = ["<map>", _tags(request.map_outline), "</map>"]
    parts += ["<briefing>", *map(_tags, request.statements), "</briefing>"]
    for chapter in request.chapters:
        parts += [
            f'<kapitel key="{_tags(chapter.key)}" titel="{_tags(chapter.title)}">'
        ]
        parts += [*map(_tags, chapter.lines), "</kapitel>"]
    return "\n".join(parts)[:max_chars]


def render_map_request(request: MapRequest, max_chars: int) -> str:
    """Instruction, current map and briefing, then the sources as delimited data."""
    parts = ["<anweisung>", _tags(request.instruction), "</anweisung>"]
    parts += ["<map>", _tags(request.map_outline), "</map>"]
    parts += ["<briefing>", *map(_tags, request.statements), "</briefing>"]
    head = "\n".join(parts)
    sources = render_sources(request.sources, max(max_chars - len(head), 0))
    return f"{head}\n\n{sources}"
    if text.endswith("?"):
        return StatementType.OPEN_POINT
    if ASSUMPTION.match(text):
        return StatementType.ASSUMPTION
    if REQUIREMENT.match(text):
        return StatementType.REQUIREMENT
    return StatementType.FACT


def _runs(text: str) -> list[Run]:
    return [Run(text=text)]


def _wanted_types(title: str) -> tuple[str, ...]:
    lowered = title.lower()
    if "annahme" in lowered or "risik" in lowered:
        return (StatementType.ASSUMPTION, StatementType.OPEN_POINT)
    if "rahmen" in lowered or "abwicklung" in lowered or "laufzeit" in lowered:
        return (StatementType.FACT, StatementType.ASSUMPTION)
    return (StatementType.REQUIREMENT, StatementType.FACT)


class DemoOfferAi:
    """Implements every AI port by quoting the sources; no network, no model."""

    model_name = DEMO_MODEL
    map_prompt_version = DEMO_PROMPT
    briefing_prompt_version = DEMO_PROMPT
    chapter_prompt_version = DEMO_PROMPT
    review_prompt_version = DEMO_PROMPT
    map_additions_prompt_version = DEMO_PROMPT

    async def propose_map(self, sources: list[SourceText]) -> ProposedMap:
        activities: list[ProposedActivity] = []
        for source in sources:
            stories = [
                story
                for sentence in _sentences(source)
                if (story := _story(sentence)) is not None
            ][:MAX_STORIES_PER_SOURCE] or [_fallback_story(source)]
            for position, story in enumerate(stories):
                story.skeleton = position == 0
                story.slice = SLICES[0] if position == 0 else SLICES[1]
            activities.append(
                ProposedActivity(
                    title=_source_name(source)[:120],
                    tasks=[ProposedTask(title=TASK_TITLE, stories=stories)],
                )
            )
        names = ", ".join(_source_name(source) for source in sources)
        return ProposedMap(
            vision=f"Angebot auf Grundlage von: {names}"[:500],
            roles=sorted(
                {
                    story.role
                    for activity in activities
                    for task in activity.tasks
                    for story in task.stories
                }
            ),
            activities=activities,
            slices=list(SLICES),
            open_questions=[
                ProposedPoint(text=f"In „{_source_name(source)}“ fehlt: {gap}")
                for source in sources
                for gap in source.gaps
            ],
        )

    async def propose_briefing(self, sources: list[SourceText]) -> ProposedBriefing:
        statements = [
            ProposedStatement(
                type=_statement_type(sentence.text),
                text=sentence.text,
                source_refs=[sentence.block_id],
            )
            for source in sources
            for sentence in _sentences(source)
        ]
        return ProposedBriefing(statements=statements[:MAX_STATEMENTS])

    async def propose_chapter(self, request: ChapterRequest) -> ProposedChapter:
        wanted = _wanted_types(request.title)
        items = [
            text
            for line in request.statements
            for kind, _, text in [line.partition(": ")]
            if kind in wanted
        ][:MAX_CHAPTER_ITEMS]
        if not items:
            note = EMPTY_CHAPTER.format(title=request.title)
            return ProposedChapter(blocks=[Paragraph(runs=_runs(note))])
        intro = CHAPTER_INTRO.format(title=request.title)
        return ProposedChapter(
            blocks=[
                Paragraph(runs=_runs(intro)),
                BulletList(items=[_runs(item) for item in items]),
            ]
        )

    async def propose_review(self, request: ReviewRequest) -> ProposedReview:
        return ProposedReview(
            findings=[
                ReviewRemark(
                    target=f"chapter:{chapter.key}",
                    message=REVIEW_EMPTY,
                    severity="Warnung",
                )
                for chapter in request.chapters
                if len(chapter.lines) < 2  # noqa: PLR2004  # intro plus one point
            ]
        )

    async def propose_map_additions(self, request: MapRequest) -> ProposedMap:
        proposed = await self.propose_map(request.sources)
        for activity in proposed.activities:
            for task in activity.tasks:
                task.stories = [
                    s for s in task.stories if s.goal not in request.map_outline
                ]
        proposed.activities = [
            a for a in proposed.activities if any(t.stories for t in a.tasks)
        ]
        proposed.open_questions = []
        return proposed

