                    const Control = CONTROLS[name];
                    return Control ? <Control key={name} /> : null;
                  })}
                </RichTextEditor.ControlsGroup>
              ))}
            </RichTextEditor.Toolbar>
          )}
          {children}
        </div>
      </div>
      <RichTextEditor.Content />
    </RichTextEditor>
  );
