css = r'''

/* Kapitel tab: the offer as one document. Outline left, the page in the
   middle (it scrolls), the chapter panel right. */
.aq-doc-outline {
  width: 280px;
  flex-shrink: 0;
  overflow: auto;
  border-right: 1px solid var(--aq-border);
  background: var(--aq-background);
  padding: 16px 10px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.aq-doc-outline-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 4px 8px 10px;
}

.aq-doc-frame-entry {
  padding: 6px 10px;
  color: var(--aq-text-tertiary);
  font-size: 12.5px;
}

.aq-doc-row {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 32px;
  padding: 0 8px;
  border-radius: 7px;
  cursor: pointer;
  font-size: 13px;
  outline: none;
}

.aq-doc-row:hover {
  background: var(--aq-hover);
}

.aq-doc-row[data-active="true"] {
  background: var(--aq-accent-soft);
  font-weight: 600;
}

.aq-doc-row[data-level="2"] {
  padding-left: 22px;
}

.aq-doc-row-title {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.aq-doc-grip {
  display: inline-flex;
  color: var(--aq-text-tertiary);
  opacity: 0;
  transition: opacity 120ms ease;
}

.aq-doc-row:hover .aq-doc-grip,
.aq-doc-sortable-item:focus-visible .aq-doc-grip {
  opacity: 1;
}

.aq-doc-sortable-item:focus-visible {
  outline: 2px solid var(--aq-accent);
  outline-offset: -2px;
  border-radius: 7px;
}

.aq-doc-sortable-item[data-dragging="true"] .aq-doc-row {
  background: var(--aq-surface);
  box-shadow: var(--aq-pane-shadow);
}

.aq-doc-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.aq-doc-type {
  padding: 0 6px;
  border-radius: 4px;
  background: var(--aq-surface);
  box-shadow: 0 0 0 1px var(--aq-border);
  color: var(--aq-tag-text);
  font-size: 10.5px;
  font-weight: 600;
  flex-shrink: 0;
}

.aq-doc-main {
  background: var(--aq-background);
  padding: 24px 16px 48px;
}

.aq-doc-page {
  max-width: 900px;
  margin: 0 auto;
  background: var(--aq-surface);
  border-radius: 6px;
  box-shadow: var(--aq-pane-shadow);
  padding: 48px 56px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--aq-text);
}

.aq-doc-block {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin: 0 -18px;
  padding: 12px 16px;
  border: 2px solid transparent;
  border-radius: 10px;
  cursor: pointer;
  transition: border-color 120ms ease;
}

.aq-doc-block:hover {
  border-color: var(--aq-border);
}

.aq-doc-block[data-selected="true"] {
  border-color: var(--aq-accent);
  padding-top: 28px;
  cursor: default;
}

.aq-doc-block-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  flex-wrap: wrap;
}

.aq-doc-block-title {
  margin: 0;
  font-size: 19px;
  font-weight: 650;
  line-height: 1.35;
}

.aq-doc-block[data-level="2"] .aq-doc-block-title {
  font-size: 16px;
}

.aq-doc-badge {
  padding: 1px 10px;
  border-radius: 999px;
  background: var(--aq-tag);
  color: var(--aq-tag-text);
  font-size: 11.5px;
  font-weight: 600;
  white-space: nowrap;
}

.aq-doc-frame {
  margin: 0 -18px;
  padding: 12px 16px;
  border: 1px dashed var(--aq-border-strong);
  border-radius: 10px;
  color: var(--aq-text-tertiary);
