.aq-doc-prose ul,
.aq-doc-prose ol {
  margin: 0 0 10px;
  padding-left: 22px;
}

.aq-doc-prose li p {
  margin: 0 0 4px;
}

.aq-doc-prose table,
.aq-doc-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  line-height: 1.4;
}

