import React, { Children, useEffect, useState } from "react";
import { DragDropContext, Draggable, Droppable } from "@hello-pangea/dnd";

// One child per id, in the same order. The list keeps its own order while the
// server confirms a move, so a dropped row does not jump back for a moment.
export function SortableList({
  ids = [],
  disabledIds = [],
  droppableId = "sortable",
  onReorder,
  className,
  itemClassName,
  children,
}) {
  const [order, setOrder] = useState(ids);
  const signature = ids.join("\u0000");
  useEffect(() => setOrder(ids), [signature]);

  const byId = {};
  Children.toArray(children).forEach((child, index) => {
    byId[ids[index]] = child;
  });

  const onDragEnd = (result) => {
    const { draggableId, source, destination } = result;
    if (!destination || destination.index === source.index) {
      return;
    }
    const next = order.filter((id) => id !== draggableId);
    next.splice(destination.index, 0, draggableId);
    setOrder(next);
    if (onReorder) {
      onReorder(draggableId, destination.index);
    }
  };

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <Droppable droppableId={droppableId}>
        {(drop) => (
          <div ref={drop.innerRef} {...drop.droppableProps} className={className}>
            {order
              .filter((id) => byId[id] !== undefined)
              .map((id, index) => (
                <Draggable
                  key={id}
                  draggableId={id}
                  index={index}
                  isDragDisabled={disabledIds.includes(id)}
                >
                  {(drag, snapshot) => (
                    <div
                      ref={drag.innerRef}
                      {...drag.draggableProps}
                      {...drag.dragHandleProps}
                      className={itemClassName}
                      data-dragging={snapshot.isDragging ? "true" : undefined}
                    >
                      {byId[id]}
                    </div>
                  )}
                </Draggable>
              ))}
            {drop.placeholder}
          </div>
        )}
      </Droppable>
    </DragDropContext>
  );
}

