        routes = [route for route, _label, _icon in PLANNING_ITEMS]
        assert routes.index(PRICES_ROUTE) == routes.index(OFFERS_ROUTE) + 1
        assert PRICES_ROUTE not in {route for route, _label, _icon in ADMIN_ITEMS}

