        for route, label, icon in PLANNING_ITEMS:
            if route in PUBLIC_ROUTES or route in VIEWER_ROUTES:
                continue
            rendered = str(_guarded_nav_item(route, label, icon))
            assert f'"{PROJECT_MANAGER_ROLE.name}"' in rendered

